-- ============================================
-- LUMA — Thème 8 : LONG 1/3 x4 — Une quête complète pour retrouver un artefact
-- ============================================


update scenarios set content = '{"characters": {"elder": "l''ancien du village", "cave_dweller": "l''habitant des grottes", "malachar": "Malachar", "narrator": "narrateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "elder", "text": "The Crystal of Aeloria has been stolen. Without it, our lands wither. You must retrieve it.", "text_fr": "Le Cristal d''Aeloria a été volé. Sans lui, nos terres se fanent. Vous devez le récupérer.", "choices": [{"text": "I accept this quest. Where should I begin searching?", "text_fr": "J''accepte cette quête. Où devrais-je commencer à chercher ?", "next": "n2"}, {"text": "Tell me more about who stole it, and why.", "text_fr": "Dites-m''en plus sur qui l''a volé, et pourquoi.", "next": "n2b"}]}, "n2": {"speaker": "elder", "text": "Begin at the Whispering Caves, where dark rumors say the thief was last seen.", "text_fr": "Commencez aux Grottes Murmurantes, où de sombres rumeurs disent que le voleur a été vu pour la dernière fois.", "choices": [{"text": "I''ll head there at once, elder.", "text_fr": "Je m''y rends immédiatement, ancien.", "next": "n3"}]}, "n2b": {"speaker": "elder", "text": "A rogue sorcerer named Malachar seeks its power for dark purposes.", "text_fr": "Un sorcier voyou nommé Malachar cherche son pouvoir à des fins sombres.", "choices": [{"text": "Then I must stop him before it''s too late.", "text_fr": "Alors je dois l''arrêter avant qu''il ne soit trop tard.", "next": "n3"}]}, "n3": {"speaker": "narrator", "text": "(You arrive at the Whispering Caves, dark and echoing with strange sounds.)", "text_fr": "(Vous arrivez aux Grottes Murmurantes, sombres et résonnant de sons étranges.)", "choices": [{"text": "(Light a torch and venture carefully into the caves.)", "text_fr": "(Allume une torche et t''aventures prudemment dans les grottes.)", "next": "n4"}]}, "n4": {"speaker": "cave_dweller", "text": "(A small creature emerges) Who dares enter my domain, hm?", "text_fr": "(Une petite créature émerge) Qui ose entrer dans mon domaine, hm ?", "choices": [{"text": "I mean no harm, I seek only information about a stolen crystal.", "text_fr": "Je ne veux aucun mal, je cherche seulement des informations sur un cristal volé.", "next": "n5"}, {"text": "A traveler on an urgent quest. I need your help, if you''ll grant it.", "text_fr": "Un voyageur en quête urgente. J''ai besoin de votre aide, si vous voulez bien l''accorder.", "next": "n5b"}]}, "n5": {"speaker": "cave_dweller", "text": "Ah, the crystal thief! He passed through, heading toward the Sunken Ruins to the south.", "text_fr": "Ah, le voleur du cristal ! Il est passé par ici, se dirigeant vers les Ruines Englouties au sud.", "choices": [{"text": "Thank you, small one. I''ll head there now.", "text_fr": "Merci, petite créature. Je m''y rends maintenant.", "next": "n6"}]}, "n5b": {"speaker": "cave_dweller", "text": "(Considers) Very well. He fled south, toward ruins swallowed by the sea long ago.", "text_fr": "(Réfléchit) Très bien. Il a fui vers le sud, vers des ruines englouties par la mer il y a longtemps.", "choices": [{"text": "I''m grateful for this knowledge. Farewell.", "text_fr": "Je vous suis reconnaissant pour ce savoir. Adieu.", "next": "n6"}]}, "n6": {"speaker": "narrator", "text": "(At the Sunken Ruins, ancient stone pillars rise from murky water.)", "text_fr": "(Aux Ruines Englouties, d''anciens piliers de pierre s''élèvent d''une eau trouble.)", "choices": [{"text": "(Wade carefully through the water toward the central structure.)", "text_fr": "(Patauge prudemment dans l''eau vers la structure centrale.)", "next": "n7"}]}, "n7": {"speaker": "malachar", "text": "(A hooded figure turns) So, someone finally came for the crystal. I expected as much.", "text_fr": "(Une silhouette encapuchonnée se retourne) Alors, quelqu''un est enfin venu pour le cristal. Je m''y attendais.", "choices": [{"text": "Malachar. Return the crystal, and no harm needs to come to you.", "text_fr": "Malachar. Rendez le cristal, et aucun mal n''a besoin de vous arriver.", "next": "n8"}, {"text": "Why do you seek its power? What drives you to this?", "text_fr": "Pourquoi cherchez-vous son pouvoir ? Qu''est-ce qui vous pousse à ça ?", "next": "n8b"}]}, "n8": {"speaker": "malachar", "text": "(Laughs darkly) You think this is about mercy? The crystal''s power belongs to those strong enough to wield it.", "text_fr": "(Rit sombrement) Vous pensez que c''est une question de pitié ? Le pouvoir du cristal appartient à ceux assez forts pour le manier.", "choices": [{"text": "Strength isn''t just power — it''s knowing when to stop.", "text_fr": "La force n''est pas que le pouvoir — c''est savoir quand s''arrêter.", "next": "n9"}]}, "n8b": {"speaker": "malachar", "text": "My village was destroyed by those who had power and no mercy. Now, I seek power of my own.", "text_fr": "Mon village a été détruit par ceux qui avaient le pouvoir et aucune pitié. Maintenant, je cherche mon propre pouvoir.", "choices": [{"text": "Vengeance won''t heal what was lost, Malachar. There''s another way.", "text_fr": "La vengeance ne guérira pas ce qui a été perdu, Malachar. Il y a une autre voie.", "next": "n9"}]}, "n9": {"speaker": "malachar", "text": "(Hesitates, crystal glowing in his palm) You speak as if you understand loss.", "text_fr": "(Hésite, le cristal brillant dans sa paume) Vous parlez comme si vous compreniez la perte.", "choices": [{"text": "I''ve lost much too. But taking this crystal will only bring more suffering.", "text_fr": "J''ai aussi beaucoup perdu. Mais prendre ce cristal n''apportera que plus de souffrance.", "next": "n10"}, {"text": "(Draw your weapon, ready to fight if words fail.)", "text_fr": "(Dégaine ton arme, prêt à combattre si les mots échouent.)", "next": "n10b"}]}, "n10": {"speaker": "malachar", "text": "(Long silence, then lowers the crystal) Perhaps... perhaps there is another way.", "text_fr": "(Long silence, puis baisse le cristal) Peut-être... peut-être y a-t-il une autre voie.", "choices": [{"text": "Return the crystal, and I''ll help you find a better path forward.", "text_fr": "Rendez le cristal, et je vous aiderai à trouver une meilleure voie.", "next": "n11"}]}, "n10b": {"speaker": "malachar", "text": "(Raises the crystal defensively) Then we have nothing left to discuss!", "text_fr": "(Lève le cristal défensivement) Alors nous n''avons plus rien à discuter !", "choices": [{"text": "(Try one final time to reach him with words instead.)", "text_fr": "(Essaie une dernière fois de l''atteindre avec des mots plutôt.)", "next": "n11b"}]}, "n11": {"speaker": "malachar", "text": "(Hands over the crystal, shoulders slumping) Take it. I''m tired of carrying this anger alone.", "text_fr": "(Tend le cristal, épaules affaissées) Prenez-le. Je suis fatigué de porter cette colère seul.", "choices": [{"text": "You don''t have to carry it alone anymore. Come, let''s find you a new path.", "text_fr": "Vous n''avez plus à la porter seul. Venez, trouvons-vous une nouvelle voie.", "next": "end_redeemed"}]}, "n11b": {"speaker": "malachar", "text": "(Pauses, crystal trembling in hand) ...Why do you still try to reach me?", "text_fr": "(Fait une pause, cristal tremblant dans sa main) ...Pourquoi essayez-vous encore de m''atteindre ?", "choices": [{"text": "Because everyone deserves a chance to choose a different path.", "text_fr": "Parce que tout le monde mérite une chance de choisir une voie différente.", "next": "end_redeemed"}]}, "end_redeemed": {"speaker": "elder", "text": "(Later, at the village) You returned not just the crystal, but a soul lost to darkness. Well done.", "text_fr": "(Plus tard, au village) Vous avez ramené non seulement le cristal, mais une âme perdue dans les ténèbres. Bien joué.", "end": true, "ending_label": "Artefact récupéré, une âme rachetée 💎🕊️"}}}'::jsonb, is_playable = true
where title = 'Une quête complète pour retrouver un artefact'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));
